<template>
  <input
    ref="inputEl"
    v-maska="moneyMask"
    inputmode="decimal"
    type="text"
    :class="
      cn(
        'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-base sm:text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50',
        $attrs.class as string
      )
    "
    :value="displayValue"
    @maska="onMaska"
    @blur="handleBlur($event)"
  />
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';

defineOptions({ inheritAttrs: false });

const attrs = useAttrs();
const props = defineProps<{ modelValue?: string | number | null }>();
const emit = defineEmits<{ 'update:modelValue': [value: string] }>();

const displayValue = computed(() => (props.modelValue != null ? String(props.modelValue) : ''));

function handleBlur(event: FocusEvent) {
  (attrs.onBlur as ((e: FocusEvent) => void) | undefined)?.(event);
}

function onMaska(e: CustomEvent<{ masked: string; unmasked: string; completed: boolean }>) {
  emit('update:modelValue', e.detail.masked.replace(/,/g, ''));
}

const moneyMask = {
  mask: '0.99',
  tokens: {
    0: { pattern: /\d/, multiple: true },
    9: { pattern: /\d/, optional: true },
  },

  preProcess: (val: string) => {
    if (!val) return '';
    const only = val.replace(/[^\d.]/g, '');
    const firstDot = only.indexOf('.');
    const cleaned = firstDot === -1 ? only : only.slice(0, firstDot + 1) + only.slice(firstDot + 1).replace(/\./g, '');
    const [intPart = '', fracPart] = cleaned.split('.');
    const cappedInt = intPart.slice(0, 9);
    return fracPart !== undefined ? `${cappedInt}.${fracPart}` : cappedInt;
  },

  postProcess: (val: string) => {
    if (!val) return '';

    if (val.length > 1 && val[0] === '0' && /\d/.test(val[1])) {
      val = '.' + val.slice(1);
    }

    if (val === '.') return '0.';

    const endsWithDot = /\.$/.test(val);

    const [i = '', f = ''] = val.split('.');
    const intPartRaw = i.replace(/^0+(?=\d)/, '') || '0';
    const fracPart = f.slice(0, 2);

    const intFormatted = new Intl.NumberFormat('en-US', {
      style: 'decimal',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(Number(intPartRaw));

    if (endsWithDot) return `${intFormatted}.`;
    if (fracPart) return `${intFormatted}.${fracPart}`;
    return intFormatted;
  },
};
</script>
